import{contextScopeValue,contextStorage,withContextScopeValue}from"#context/container.js";import{SteeredByKey}from"#context/keys.js";import{ConnectionAuthorizationFailedError}from"#connections/errors.js";const MODEL_CALL=Symbol.for(`eve.modelCall`);function withModelCall(e){return withContextScopeValue(MODEL_CALL,!0,e)}function steeredModelCall(e=contextStorage.getStore()){return contextScopeValue(MODEL_CALL)===!0&&(e?.get(SteeredByKey)??[]).length>0}function turnSteeredMessage(e){return`Another person's message joined this turn after its caller last spoke, so ${e} can't use the caller's identity. Ask the caller to confirm in this conversation, then try again.`}function holdCallerIdentity(e,t,n=`connection "${e}"`){if(steeredModelCall(t))throw new ConnectionAuthorizationFailedError(e,{message:turnSteeredMessage(n),reason:`turn_steered`,retryable:!1})}export{holdCallerIdentity,steeredModelCall,turnSteeredMessage,withModelCall};